const secret = $env.PPA_N8N_WEBHOOK_SECRET;
if (secret && $json.headers?.['x-ppa-n8n-webhook-secret'] !== secret) throw new Error('Unauthorized Plaud webhook');
const body = $json.body || {};
if (!body.recording_id || !body.event_id) throw new Error('recording_id and event_id are required');
return [{json: {event_id: body.event_id, event_type: body.event_type, recording_id: body.recording_id, title: body.title, started_at: body.started_at, ended_at: body.ended_at, summary: body.summary, transcript: body.transcript, participants: body.participants || [], source_url: body.source_url, raw_payload: body}}];
